"""`index.md`: the wiki's orientation, generated by the host after each run, never by the model.

It lists each page as a link with its one-line summary, grouped by type. Under each type the
active pages come first, the most recently updated first, so what's live is at the top; the
rest follow by slug.
"""

from __future__ import annotations

from collections.abc import Iterable
from datetime import date
from pathlib import Path

from pa_core.librarian.wiki import ACTIVE, INDEX, PAGE_TYPES, Page, pages


def render_index(listed: Iterable[Page]) -> str:
    """The index of `listed`: a section per page type that has pages, in `index_order`."""
    by_folder: dict[str, list[Page]] = {}
    for page in listed:
        by_folder.setdefault(page.folder, []).append(page)
    parts = ["# Index\n"]
    for folder, page_type in PAGE_TYPES.items():
        group = sorted(by_folder.get(folder, ()), key=index_order)
        if group:
            entries = "".join(f"- [[{page.slug}]]: {page.summary}\n" for page in group)
            parts.append(f"## {page_type.heading}\n\n{entries}")
    if len(parts) == 1:
        parts.append("No pages yet.\n")
    return "\n".join(parts)


def index_order(page: Page) -> tuple[int, int, str]:
    """Where `page` sorts among its type's pages: active pages by `updated`, newest first
    (by slug within a day, and last without a date), then every other page by slug."""
    if page.fields.get("status") != ACTIVE:
        return (1, 0, page.slug)
    return (0, -_updated(page).toordinal(), page.slug)


def _updated(page: Page) -> date:
    """The page's `updated` date, or the earliest date there is when it isn't one (lint fails
    such a page)."""
    value = page.fields.get("updated")
    try:
        return date.fromisoformat(value) if isinstance(value, str) else date.min
    except ValueError:
        return date.min


def write_index(tree: Path) -> None:
    """Regenerates `index.md` in the wiki at `tree` from its pages."""
    (tree / INDEX).write_text(render_index(pages(tree)), encoding="utf-8")
